    const ids=new Set(trips.map(t=>t.id));if(ids.size!==trips.length)throw Error('IDs viaggio duplicati');let plans=raw.plans.filter(x=>x&&ids.has(x.tripId)).map(x=>({id:trim(x.id)||uid(),tripId:trim(x.tripId),type:planTypes[x.type]?x.type:'other',title:trim(x.title),date:dat(x.date),time:/^([01]\d|2[0-3]):[0-5]\d$/.test(x.time||'')?x.time:'',location:trim(x.location),cost:Math.max(0,Math.min(1000000000,Number(x.cost)||0)),status:['idea','booked','done'].includes(x.status)?x.status:'idea',description:trim(x.description),url:safeUrl(trim(x.url))}));
