    const creating=mode==='create';
    root.innerHTML=`<div class="vault-screen"><section class="vault-panel" aria-labelledby="vault-title"><div class="eyebrow">ROTTA · ARCHIVIO PRIVATO</div><h1 id="vault-title">${creating?'Proteggi i tuoi viaggi':'Sblocca ROTTA'}</h1><p class="helper">${creating?'Scegli una passphrase di almeno 14 caratteri: i tuoi dati saranno cifrati localmente con AES-256-GCM.':'Inserisci la passphrase: non viene inviata su internet e non è recuperabile.'}</p><form id="vault-form"><div class="field"><label for="vault-password">Passphrase</label><input id="vault-password" type="password" autocomplete="${creating?'new-password':'current-password'}" required minlength="${creating?'14':'1'}" maxlength="200"></div>${creating?'<div class="field"><label for="vault-confirm">Conferma passphrase</label><input id="vault-confirm" type="password" autocomplete="new-password" required minlength="14" maxlength="200"></div>':''}<button class="btn primary" id="vault-submit" type="submit">${creating?'Crea archivio cifrato':'Sblocca archivio'}</button></form><p id="vault-error" class="vault-error" role="alert">${esc(message)}</p><p class="helper vault-foot">⚠️ Conserva la passphrase in un password manager. Se la perdi, non possiamo recuperare i dati. Il backup cifrato usa la stessa passphrase.</p></section></div>`;
