  function updateNav(){const nav=navItems.map(([id,label,icon])=>`<button class="nav-button ${page===id?'active':''}" data-nav="${id}" ${page===id?'aria-current="page"':''}>${ico(icon)}<span>${label}</span></button>`).join('');document.getElementById('sidenav').innerHTML=nav+'<div class="nav-label" style="margin-top:20px">STRUMENTI</div>'+`<button class="nav-button ${page==='settings'?'active':''}" data-nav="settings">${ico('settings')}<span>Impostazioni</span></button>`;
    document.getElementById('mobile-nav').innerHTML=navItems.map(([id,label,icon])=>`<button data-nav="${id}" class="${page===id?'active':''}" ${page===id?'aria-current="page"':''}>${ico(icon)}<span>${id==='home'?'Home':id==='plan'?'Piano':id==='budget'?'Spese':id==='tasks'?'Da fare':'AI'}</span></button>`).join('')}
