  function emptyTrips(){return `<div class="card" style="padding:42px 24px;text-align:center;margin-top:9vh;max-width:650px;margin-inline:auto"><div style="font-size:43px;margin-bottom:12px">🧭</div><div class="kicker">IL TUO PROSSIMO CAPITOLO</div><h1 style="font-size:38px;margin:10px 0">Dove si parte?</h1><p class="helper" style="max-width:420px;margin:0 auto 21px">Crea il primo viaggio e organizza voli, zone, alloggi, eventi, budget e promemoria. Nessun account richiesto.</p><button class="btn primary" data-action="add-trip">${ico('plus')} Crea il primo viaggio</button></div>`}
